def copy_switches(apps, schema_editor):
    """The three on/off switches become rows of the permissions table, nobody's access changing."""
    Permission = apps.get_model("cluster", "Permission")
    Grant = apps.get_model("cluster", "Grant")
    Membership = apps.get_model("cluster", "Membership")
    perms = {}
    for code, name, description, owner_controlled, order in PERMISSIONS:
        perms[code], _ = Permission.objects.get_or_create(code=code, defaults={
            "name": name, "description": description, "owner_controlled": owner_controlled, "sort_order": order})
    for m in Membership.objects.all():
        for code, field in (("money", "money_access"), ("ids", "see_full_ids"), ("delete", "can_delete")):
            if getattr(m, field):
                Grant.objects.get_or_create(membership=m, permission=perms[code])


